function bookCard(book) {
  return `<li class="book-card">
  <div><a href="/books/${book.id}"><strong>${escapeHtml(book.title)}</strong></a> <small>by ${escapeHtml(book.author)}</small></div>
  <div style="display:flex;gap:6px;align-items:center">
    ${book.status !== 'finished' ? `<form method="POST" action="/books/${book.id}/finish" style="margin:0"><button type="submit">Mark as finished</button></form>` : `<small>✓ Finished</small>`}
  </div>
</li>`;
}

function homePage(books) {
  const reading = books.filter(b => b.status !== 'finished');
  const finished = books.filter(b => b.status === 'finished');

  const readingHtml = reading.length
    ? `<ul class="book-list">${reading.map(bookCard).join('')}</ul>`
    : `<div class="empty">No books currently reading. Add one below!</div>`;

  const finishedHtml = finished.length
    ? `<ul class="book-list">${finished.map(bookCard).join('')}</ul>`
    : `<div class="empty">No finished books yet.</div>`;

  return layout('My Books', `
<header><h1>My Books</h1></header>
<p class="subtitle">Track what you're reading. Books are saved to a JSON file.</p>

<h2>Currently Reading</h2>
${readingHtml}

<h2>Finished</h2>
${finishedHtml}

<h2>Add a Book</h2>
<form class="add-form" method="POST" action="/books">
