import express from 'express';
import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

const app = express();
const PORT = process.env.PORT || 3000;

const DATA_DIR = path.join(__dirname, 'data');
const DATA_FILE = path.join(DATA_DIR, 'books.json');
const ROOT_DATA_FILE = path.join(__dirname, 'books.json');

function ensureDataFile() {
  if (!fs.existsSync(DATA_DIR)) fs.mkdirSync(DATA_DIR, { recursive: true });
  if (!fs.existsSync(DATA_FILE)) {
    if (fs.existsSync(ROOT_DATA_FILE)) {
      fs.copyFileSync(ROOT_DATA_FILE, DATA_FILE);
    } else {
      fs.writeFileSync(DATA_FILE, '[]', 'utf8');
    }
  }
}

function loadBooks() {
  ensureDataFile();
  try {
    const raw = fs.readFileSync(DATA_FILE, 'utf8');
    const data = JSON.parse(raw);
    return Array.isArray(data) ? data : [];
  } catch {
    return [];
  }
}

function saveBooks(books) {
  ensureDataFile();
  const json = JSON.stringify(books, null, 2);
  fs.writeFileSync(DATA_FILE, json, 'utf8');
  try {
    fs.writeFileSync(ROOT_DATA_FILE, json, 'utf8');
  } catch {}
}

function generateId() {
  return Date.now().toString(36) + Math.random().toString(36).slice(2, 7);
}

function escapeHtml(str) {
  if (str == null) return '';
  return String(str)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

app.use(express.urlencoded({ extended: true }));
app.use(express.json());

const style = `
*{box-sizing:border-box}body{font-family:system-ui,-apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;max-width:800px;margin:0 auto;padding:24px;color:#1a1a1a;background:#fafaf9}a{color:#2563eb;text-decoration:none}a:hover{text-decoration:underline}h1{margin:0 0 8px;font-size:28px}h2{margin:28px 0 12px;font-size:20px;border-bottom:2px solid #e5e7eb;padding-bottom:6px}.subtitle{color:#6b7280;margin-bottom:20px}form.add-form{background:#fff;border:1px solid #e5e7eb;border-radius:10px;padding:16px;margin:20px 0;display:flex;flex-direction:column;gap:10px}form.add-form input,form.add-form textarea{padding:8px 10px;border:1px solid #d1d5db;border-radius:8px;font:inherit}form.add-form textarea{resize:vertical;min-height:60px}.row{display:flex;gap:10px}.row input{flex:1}button{cursor:pointer;background:#111827;color:#fff;border:none;border-radius:8px;padding:8px 14px;font-weight:600}button.secondary{background:#e5e7eb;color:#111827}button:hover{opacity:.9}.book-list{list-style:none;padding:0;display:flex;flex-direction:column;gap:8px}.book-card{background:#fff;border:1px solid #e5e7eb;border-radius:10px;padding:12px 14px;display:flex;justify-content:space-between;align-items:center;gap:12px}.book-card small{color:#6b7280}.empty{color:#9ca3af;font-style:italic;background:#fff;border:1px dashed #e5e7eb;border-radius:10px;padding:14px}.detail{background:#fff;border:1px solid #e5e7eb;border-radius:10px;padding:18px}.meta{color:#6b7280;margin:6px 0}.notes{white-space:pre-wrap;background:#f9fafb;border:1px solid #e5e7eb;border-radius:8px;padding:12px;margin-top:12px}.actions{display:flex;gap:8px;margin-top:16px;flex-wrap:wrap}.share-box{margin-top:14px;background:#f3f4f6;border-radius:8px;padding:10px;font-size:14px;word-break:break-all}header{display:flex;justify-content:space-between;align-items:center}
`;

function layout(title, body) {
  return `<!DOCTYPE html>
<html lang="en">
<head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${escapeHtml(title)}</title><style>${style}</style></head>
<body>${body}</body>
</html>`;
}

function bookCard(book) {
  return `<li class="book-card">
  <div><a href="/books/${book.id}"><strong>${escapeHtml(book.title)}</strong></a> <small>by ${escapeHtml(book.author)}</small></div>
  <div style="display:flex;gap:6px;align-items:center">
    ${book.status !== 'finished' ? `<form method="POST" action="/books/${book.id}/finish" style="margin:0"><button type="submit">Mark as finished</button></form>` : `<small>✓ Finished</small>`}
  </div>
</li>`;
}

function homePage(books) {
  const reading = books.filter(b => b.status !== 'finished');
  const finished = books.filter(b => b.status === 'finished');

  const readingHtml = reading.length
    ? `<ul class="book-list">${reading.map(bookCard).join('')}</ul>`
    : `<div class="empty">No books currently reading. Add one below!</div>`;

  const finishedHtml = finished.length
    ? `<ul class="book-list">${finished.map(bookCard).join('')}</ul>`
    : `<div class="empty">No finished books yet.</div>`;

  return layout('My Books', `
<header><h1>My Books</h1></header>
<p class="subtitle">Track what you're reading. Books are saved to a JSON file.</p>

<h2>Currently Reading</h2>
${readingHtml}

<h2>Finished</h2>
${finishedHtml}

<h2>Add a Book</h2>
<form class="add-form" method="POST" action="/books">
  <div class="row">
    <input name="title" placeholder="Title" required aria-label="Title" />
    <input name="author" placeholder="Author" required aria-label="Author" />
  </div>
  <textarea name="notes" placeholder="Notes (optional)"></textarea>
  <div><button type="submit">Add book</button></div>
</form>
`);
}

function detailPage(book, req) {
  const shareUrl = `${req.protocol}://${req.get('host')}/books/${book.id}`;
  return layout(book.title, `
<p><a href="/">← Back to list</a></p>
<div class="detail">
  <h1>${escapeHtml(book.title)}</h1>
  <p class="meta">by <strong>${escapeHtml(book.author)}</strong> · <em>${book.status === 'finished' ? 'Finished' : 'Currently reading'}</em></p>
  ${book.notes ? `<div class="notes">${escapeHtml(book.notes)}</div>` : `<p class="meta">No notes yet.</p>`}
  <div class="actions">
    ${book.status !== 'finished' ? `<form method="POST" action="/books/${book.id}/finish"><button type="submit">Mark as finished</button></form>` : ``}
    <a href="/" class="secondary" style="display:inline-flex;align-items:center;padding:8px 14px;background:#e5e7eb;border-radius:8px;color:#111827;font-weight:600">Back</a>
  </div>
  <div class="share-box">
    <strong>Share this book:</strong><br>
    <a href="${shareUrl}">${shareUrl}</a>
    <div style="margin-top:6px;color:#6b7280;font-size:13px">Send this link to someone to share this book.</div>
  </div>
</div>
`);
}

app.get('/', (req, res) => {
  const books = loadBooks();
  res.send(homePage(books));
});

app.get('/books/:id', (req, res) => {
  const books = loadBooks();
  const book = books.find(b => b.id === req.params.id);
  if (!book) return res.status(404).send(layout('Not found', `<h1>Book not found</h1><p><a href="/">Back to list</a></p>`));
  res.send(detailPage(book, req));
});

app.post('/books', (req, res) => {
  const { title, author, notes } = req.body;
  if (!title || !author) {
    const wantsJson = req.headers.accept?.includes('application/json') || req.headers['content-type']?.includes('application/json');
    if (wantsJson) return res.status(400).json({ error: 'title and author required' });
    return res.status(400).send('title and author required');
  }
  const books = loadBooks();
  const book = {
    id: generateId(),
    title: String(title).trim(),
    author: String(author).trim(),
    notes: notes ? String(notes).trim() : '',
    status: 'reading',
    createdAt: new Date().toISOString()
  };
  books.push(book);
  saveBooks(books);

  const wantsJson = req.headers.accept?.includes('application/json');
  if (wantsJson) return res.status(201).json(book);
  res.redirect('/');
});

app.post('/books/:id/finish', (req, res) => {
  const books = loadBooks();
  const book = books.find(b => b.id === req.params.id);
  if (!book) {
    const wantsJson = req.headers.accept?.includes('application/json');
    if (wantsJson) return res.status(404).json({ error: 'not found' });
    return res.status(404).send('not found');
  }
  book.status = 'finished';
  book.finishedAt = new Date().toISOString();
  saveBooks(books);
  const wantsJson = req.headers.accept?.includes('application/json');
  if (wantsJson) return res.json(book);
  const referer = req.get('referer') || '';
  if (referer.includes(`/books/${book.id}`)) return res.redirect(`/books/${book.id}`);
  res.redirect('/');
});

app.post('/api/books/:id/finish', (req, res) => {
  const books = loadBooks();
  const book = books.find(b => b.id === req.params.id);
  if (!book) return res.status(404).json({ error: 'not found' });
  book.status = 'finished';
  book.finishedAt = new Date().toISOString();
  saveBooks(books);
  res.json(book);
});

app.get('/api/books', (req, res) => {
  res.json(loadBooks());
});

app.get('/api/books/:id', (req, res) => {
  const books = loadBooks();
  const book = books.find(b => b.id === req.params.id);
  if (!book) return res.status(404).json({ error: 'not found' });
  res.json(book);
});

app.post('/api/books', (req, res) => {
  const { title, author, notes } = req.body;
  if (!title || !author) return res.status(400).json({ error: 'title and author required' });
  const books = loadBooks();
  const book = {
    id: generateId(),
    title: String(title).trim(),
    author: String(author).trim(),
    notes: notes ? String(notes).trim() : '',
    status: 'reading',
    createdAt: new Date().toISOString()
  };
  books.push(book);
  saveBooks(books);
  res.status(201).json(book);
});

app.patch('/api/books/:id', (req, res) => {
  const books = loadBooks();
  const book = books.find(b => b.id === req.params.id);
  if (!book) return res.status(404).json({ error: 'not found' });
  if (req.body.status) book.status = req.body.status;
  if (req.body.notes !== undefined) book.notes = req.body.notes;
  if (req.body.title) book.title = req.body.title;
  if (req.body.author) book.author = req.body.author;
  if (book.status === 'finished' && !book.finishedAt) book.finishedAt = new Date().toISOString();
  saveBooks(books);
  res.json(book);
});

export { app, loadBooks, saveBooks, DATA_FILE, ROOT_DATA_FILE };

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  app.listen(PORT, () => console.log(`books app listening on http://localhost:${PORT}`));
}

