const DATA_DIR = path.join(__dirname, 'data');
const DATA_FILE = path.join(DATA_DIR, 'books.json');
const ROOT_DATA_FILE = path.join(__dirname, 'books.json');

function ensureDataFile() {
  if (!fs.existsSync(DATA_DIR)) fs.mkdirSync(DATA_DIR, { recursive: true });
  if (!fs.existsSync(DATA_FILE)) {
    if (fs.existsSync(ROOT_DATA_FILE)) {
      fs.copyFileSync(ROOT_DATA_FILE, DATA_FILE);
    } else {
      fs.writeFileSync(DATA_FILE, '[]', 'utf8');
    }
  }
}

function loadBooks() {
  ensureDataFile();
  try {
    const raw = fs.readFileSync(DATA_FILE, 'utf8');
    const data = JSON.parse(raw);
    return Array.isArray(data) ? data : [];
  } catch {
    return [];
  }
}

function saveBooks(books) {
  ensureDataFile();
  const json = JSON.stringify(books, null, 2);
  fs.writeFileSync(DATA_FILE, json, 'utf8');
  try {
    fs.writeFileSync(ROOT_DATA_FILE, json, 'utf8');
  } catch {}
}

