    const wantsJson = req.headers.accept?.includes('application/json') || req.headers['content-type']?.includes('application/json');
    if (wantsJson) return res.status(404).json({ error: 'not found' });
    return res.status(404).send('not found');
  }
  book.status = 'finished';
  book.finishedAt = new Date().toISOString();
  saveBooks(books);
  const wantsJson = req.headers.accept?.includes('application/json') || req.headers['content-type']?.includes('application/json');
  if (wantsJson) return res.json(book);
  const referer = req.get('referer') || '';
  if (referer.includes(`/books/${book.id}`) || referer.includes(`/book/${book.id}`)) return res.redirect(303, `/books/${book.id}`);
  res.redirect(303, '/');
}

app.post('/books/:id/complete', finishBook);
app.post('/books/:id/completed', finishBook);
app.post('/books/:id/finished', finishBook);
app.post('/book/:id/finish', finishBook);
app.post('/book/:id/complete', finishBook);

app.get('/api/books', (req, res) => {
  res.json(loadBooks());
});

app.get('/api/books/:id', (req, res) => {
  const books = loadBooks();
  const book = books.find(b => b.id === req.params.id);
  if (!book) return res.status(404).json({ error: 'not found' });
  res.json(book);
});

app.post('/api/books', (req, res) => {
  const { title, author, notes } = req.body;
  if (!title || !author) return res.status(400).json({ error: 'title and author required' });
  const books = loadBooks();
  const book = {
    id: generateId(),
    title: String(title).trim(),
    author: String(author).trim(),
    notes: notes ? String(notes).trim() : '',
    status: 'reading',
    createdAt: new Date().toISOString()
  };
  books.push(book);
  saveBooks(books);
  res.status(201).json(book);
});

app.patch('/api/books/:id', (req, res) => {
  const books = loadBooks();
  const book = books.find(b => b.id === req.params.id);
  if (!book) return res.status(404).json({ error: 'not found' });
  if (req.body.status) book.status = req.body.status;
  if (req.body.notes !== undefined) book.notes = req.body.notes;
  if (req.body.title) book.title = req.body.title;
  if (req.body.author) book.author = req.body.author;
  if (book.status === 'finished' && !book.finishedAt) book.finishedAt = new Date().toISOString();
  saveBooks(books);
  res.json(book);
});

export { app, loadBooks, saveBooks, DATA_FILE, ROOT_DATA_FILE };

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  app.listen(PORT, () => console.log(`books app listening on http://localhost:${PORT}`));
}

